// Base64-encoded copy of public/logo.webp, embedded so email code can
// attach the logo as a CID inline image without depending on filesystem
// layout at runtime (which differs between vite dev and the bundled Nitro
// .output/server build) or a publicly reachable URL for the deployed app.
// Regenerate if the logo changes:
//   node -e "console.log(require('fs').readFileSync('public/logo.webp').toString('base64'))"
export const LOGO_BASE64 =
  "";
export const LOGO_MIME = "image/webp";
